// Small, dependency-free helpers: responses, validation, crypto, rate limiting.
// Uses only Web Platform APIs (fetch, crypto.subtle, TextEncoder) so it runs in Workers and Node 22.

export function json(body, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      ...extraHeaders,
    },
  });
}

// Install IDs are random UUID v4 values generated by the app. Rejecting anything else keeps junk
// and probing strings out of the database.
const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

export function isInstallId(value) {
  return typeof value === 'string' && UUID_V4.test(value);
}

// Indian mobile numbers only: accepts "9876543210", "+91 98765 43210", "09876543210", "919876543210".
// Returns the 10-digit national number, or null if it does not look like one.
export function normalisePhone(raw) {
  if (typeof raw !== 'string') return null;
  const digits = raw.replace(/\D/g, '');
  if (digits.length < 10 || digits.length > 12) return null;
  const national = digits.slice(-10);
  return /^[6-9]\d{9}$/.test(national) ? national : null;
}

const encoder = new TextEncoder();

function toHex(buffer) {
  return [...new Uint8Array(buffer)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

export async function hmacSha256Hex(secret, message) {
  const key = await crypto.subtle.importKey(
    'raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return toHex(await crypto.subtle.sign('HMAC', key, encoder.encode(message)));
}

export async function sha256Hex(message) {
  return toHex(await crypto.subtle.digest('SHA-256', encoder.encode(message)));
}

// Constant-time comparison of two strings (length differences leak, which is fine for fixed-length
// hex digests).
export function constantTimeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// Compare a secret without leaking its length: hash both sides first.
export async function secretsMatch(provided, expected) {
  if (!provided || !expected) return false;
  return constantTimeEqual(await sha256Hex(provided), await sha256Hex(expected));
}

export function randomHex(bytes) {
  return toHex(crypto.getRandomValues(new Uint8Array(bytes)));
}

// Fixed-window counter stored in D1. Returns true while the caller is within the limit.
// `subject` is hashed so raw phone numbers or IPs are never written into the rate-limit table.
export async function withinLimit(db, scope, subject, limit, windowSeconds, nowSeconds) {
  const window = Math.floor(nowSeconds / windowSeconds);
  const bucket = `${scope}:${(await sha256Hex(subject)).slice(0, 24)}:${window}`;
  const row = await db
    .prepare(
      `INSERT INTO rate_limits (bucket, count, expires_at) VALUES (?, 1, ?)
       ON CONFLICT(bucket) DO UPDATE SET count = count + 1
       RETURNING count`)
    .bind(bucket, (window + 1) * windowSeconds + 60)
    .first();
  return row.count <= limit;
}

export function purgeExpiredLimits(db, nowSeconds) {
  return db.prepare('DELETE FROM rate_limits WHERE expires_at < ?').bind(nowSeconds).run();
}
